import{_ as i,o as t,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Next Generation Erasure Coding | Ceph Days London 2024","description":"","frontmatter":{"title":"Next Generation Erasure Coding | Ceph Days London 2024","date":"2024-08-23T00:00:00.000Z","updated":"2024-08-24T00:00:00.000Z","tags":["Ceph","纠删码","性能优化","分布式存储","Erasure Coding"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Next_Generation_Erasure_Coding_Ceph_Days_London_2024.md","filePath":"posts/2024/Next_Generation_Erasure_Coding_Ceph_Days_London_2024.md","lastUpdated":1780459816000}'),e={name:"posts/2024/Next_Generation_Erasure_Coding_Ceph_Days_London_2024.md"};function r(s,l,p,a,_,g){return t(),o("div",null,[...l[0]||(l[0]=[n("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： [请填写会议时间]</p><p><strong>参会人员</strong>： Bill（存储开发人员），Seth（其他参会人员）</p><p><strong>会议主题</strong>： Ceph 分布式存储中 Erasure Coding 优化方案讨论</p><p><strong>会议内容</strong>：</p><ul><li><p><strong>背景介绍</strong>：</p><ul><li>当前 Ceph 存储系统中，对象存储使用纠删码，块存储和文件存储使用副本池。</li><li>纠删码的优势在于降低存储成本，但性能不如副本池。</li><li>目标是提高纠删码的性能，使其在块存储和文件存储中更具竞争力。</li></ul></li><li><p><strong>性能瓶颈分析</strong>：</p><ul><li>网络带宽：网络连接限制性能。</li><li>IOPS：硬盘性能限制，尤其是使用 HDD 时。</li><li>延迟：读取和写入数据的延迟。</li><li>CPU：CPU 资源限制。</li></ul></li><li><p><strong>优化方案</strong>：</p><ul><li><strong>读取优化</strong>： <ul><li>部分读取：仅读取所需数据，减少网络带宽和 CPU 开销。</li><li>直接读取：客户端直接向存储数据的 OSD 发送读取请求，减少网络跳数和 CPU 开销。</li></ul></li><li><strong>写入优化</strong>： <ul><li>简单覆盖优化：仅读取未修改的数据，合并新数据，计算新的校验码，并仅写入修改的数据和校验码。</li><li>Apparity Delta 写入优化：读取旧数据和新数据，计算 Delta，并应用于校验码，减少 IOPS。</li></ul></li><li><strong>块大小优化</strong>： <ul><li>增加块大小：提高 IOPS，减少网络带宽和 CPU 开销。</li><li>根据对象大小动态调整块大小：针对不同大小的对象选择合适的块大小，提高效率。</li></ul></li></ul></li><li><p><strong>行动计划</strong>：</p><ul><li>完成部分读取优化，并发布到主分支。</li><li>研究并实现其他优化方案。</li><li>在 T 版本中提供纠删码优化功能。</li></ul></li></ul><p><strong>讨论要点</strong>：</p><ul><li>部分读取和直接读取优化对客户端性能的影响。</li><li>Apparity Delta 写入优化对延迟的影响。</li><li>块大小优化对小对象的影响。</li><li>优化方案的复杂性和实施难度。</li></ul><p><strong>结论</strong>：</p><p>通过优化纠删码，可以提高其在块存储和文件存储中的性能，使其更具竞争力。会议确定了具体的优化方案和行动计划，并讨论了相关技术细节。</p><p><strong>改进点</strong>：</p><ol><li>在“背景介绍”中明确指出纠删码在对象存储中的应用。</li><li>在“优化方案”中增加了“块大小优化”的具体内容。</li><li>在“行动计划”中增加了具体版本号的提及。</li><li>在“讨论要点”中增加了对优化方案影响的讨论。</li></ol>",12)])])}const C=i(e,[["render",r]]);export{d as __pageData,C as default};
